import dayjs from 'dayjs';
import type { Ref } from 'react';
import { Button, CloseButton, Group, Input, Stack, Surface, Text, TextInput } from '@mantine/core';
import { YearPickerInput } from '@mantine/dates';
import type { JobApplicationFormType } from './types';
import { createPosition } from './values';

interface PositionsListProps {
  form: JobApplicationFormType;
  addPositionRef: Ref<HTMLButtonElement>;
}

export function PositionsList({ form, addPositionRef }: PositionsListProps) {
  const positions = form.useWatchValue('positions');
  const currentYear = dayjs().format('YYYY-MM-DD');

  return (
    <Stack gap="xs">
      <Input.Label required>Previous positions</Input.Label>

      {positions.length === 0 && <Text size="sm">No positions added</Text>}

      {positions.map((position, index) => (
        <Surface key={position.id} level={0} withBorder p="md" radius="md">
          <Group justify="space-between" mb="xs">
            <Text size="sm" fw={500}>
              Position {index + 1}
            </Text>
            <CloseButton
              aria-label={`Remove position ${index + 1}`}
              onClick={() => form.removeListItem('positions', index)}
            />
          </Group>
          <Group grow align="flex-start">
            <TextInput
              label="Company"
              placeholder="Company"
              withAsterisk
              {...form.getInputProps(`positions.${index}.company`)}
            />
            <TextInput
              label="Title"
              placeholder="Title"
              withAsterisk
              {...form.getInputProps(`positions.${index}.title`)}
            />
            <YearPickerInput
              type="range"
              label="Years"
              placeholder="Start year – end year"
              withAsterisk
              allowSingleDateInRange
              maxDate={currentYear}
              {...form.getInputProps(`positions.${index}.years`)}
            />
          </Group>
        </Surface>
      ))}

      {form.errors.positions && <Input.Error>{form.errors.positions}</Input.Error>}

      <Group>
        <Button
          ref={addPositionRef}
          variant="default"
          onClick={() => form.insertListItem('positions', createPosition())}
        >
          Add position
        </Button>
      </Group>
    </Stack>
  );
}

import dayjs from 'dayjs';
import type { ReactNode } from 'react';
import { Anchor, Group, SimpleGrid, Stack, Surface, Text, Title } from '@mantine/core';
import type { JobApplicationFormType } from './types';
import { STEPS, WORK_MODE_LABELS } from './values';

interface ReviewStepProps {
  form: JobApplicationFormType;
  onEdit: (step: number) => void;
}

function display(value: ReactNode) {
  return value === '' || value === null || value === undefined ? '—' : value;
}

function ReviewItem({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div>
      <Text size="xs">{label}</Text>
      <Text size="sm" style={{ overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }}>
        {display(value)}
      </Text>
    </div>
  );
}

function ReviewSection({
  step,
  onEdit,
  children,
}: {
  step: number;
  onEdit: (step: number) => void;
  children: ReactNode;
}) {
  return (
    <Surface component="section" withBorder p="md" radius="md" aria-label={STEPS[step]}>
      <Group justify="space-between" mb="sm">
        <Title order={4}>{STEPS[step]}</Title>
        <Anchor
          component="button"
          type="button"
          size="sm"
          aria-label={`Edit ${STEPS[step].toLowerCase()}`}
          onClick={() => onEdit(step)}
        >
          Edit
        </Anchor>
      </Group>
      {children}
    </Surface>
  );
}

export function ReviewStep({ form, onEdit }: ReviewStepProps) {
  const values = form.getValues();

  return (
    <Stack>
      <ReviewSection step={0} onEdit={onEdit}>
        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <ReviewItem label="First name" value={values.firstName} />
          <ReviewItem label="Last name" value={values.lastName} />
          <ReviewItem label="Email" value={values.email} />
          <ReviewItem label="Phone" value={values.phone} />
          <ReviewItem label="LinkedIn URL" value={values.linkedinUrl} />
        </SimpleGrid>
      </ReviewSection>

      <ReviewSection step={1} onEdit={onEdit}>
        <Stack gap="sm">
          <SimpleGrid cols={{ base: 1, sm: 2 }}>
            <ReviewItem label="Current title" value={values.currentTitle} />
            <ReviewItem label="Years of experience" value={values.yearsOfExperience} />
          </SimpleGrid>
          <ReviewItem
            label="Previous positions"
            value={values.positions
              .map(
                (position) =>
                  `${position.title} at ${position.company}, ${dayjs(position.years[0]).year()}–${dayjs(position.years[1]).year()}`
              )
              .join('\n')}
          />
        </Stack>
      </ReviewSection>

      <ReviewSection step={2} onEdit={onEdit}>
        <Stack gap="sm">
          <SimpleGrid cols={{ base: 1, sm: 2 }}>
            <ReviewItem
              label="Earliest start date"
              value={values.startDate && dayjs(values.startDate).format('MMMM D, YYYY')}
            />
            <ReviewItem
              label="Expected salary"
              value={
                typeof values.expectedSalary === 'number'
                  ? `$${values.expectedSalary.toLocaleString('en-US')}`
                  : ''
              }
            />
            <ReviewItem
              label="Work arrangement"
              value={values.workMode && WORK_MODE_LABELS[values.workMode]}
            />
          </SimpleGrid>
          <ReviewItem label="Notes" value={values.notes} />
        </Stack>
      </ReviewSection>
    </Stack>
  );
}

import type { UseFormReturnType } from '@mantine/form';

export type WorkMode = 'remote' | 'hybrid' | 'on-site';

export interface Position {
  id: string;
  company: string;
  title: string;
  years: [string | null, string | null];
}

export interface JobApplicationValues {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  linkedinUrl: string;
  currentTitle: string;
  yearsOfExperience: number | string;
  positions: Position[];
  startDate: string | null;
  expectedSalary: number | string;
  workMode: WorkMode | '';
  notes: string;
}

export type JobApplicationFormType = UseFormReturnType<JobApplicationValues>;

import dayjs from 'dayjs';
import {
  formRootRule,
  hasLength,
  isEmail,
  isInRange,
  isNotEmpty,
  isUrl,
  when,
  type FormRulesRecord,
} from '@mantine/form';
import { randomId } from '@mantine/hooks';
import type { JobApplicationValues, Position, WorkMode } from './types';

export const NOTES_MAX_LENGTH = 500;

export const STEPS = ['Personal', 'Experience', 'Availability', 'Review'] as const;

export const REVIEW_STEP = STEPS.length - 1;

export const WORK_MODE_LABELS: Record<WorkMode, string> = {
  remote: 'Remote',
  hybrid: 'Hybrid',
  'on-site': 'On-site',
};

export function createPosition(): Position {
  return { id: randomId(), company: '', title: '', years: [null, null] };
}

export function getInitialValues(): JobApplicationValues {
  return {
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    linkedinUrl: '',
    currentTitle: '',
    yearsOfExperience: '',
    positions: [createPosition()],
    startDate: null,
    expectedSalary: '',
    workMode: '',
    notes: '',
  };
}

export const validationRules: FormRulesRecord<JobApplicationValues> = {
  firstName: isNotEmpty('First name is required'),
  lastName: isNotEmpty('Last name is required'),
  email: isEmail('Enter a valid email'),
  linkedinUrl: when(
    (values) => values.linkedinUrl.trim() !== '',
    isUrl('Enter a valid URL, for example https://www.linkedin.com/in/your-name')
  ),
  currentTitle: isNotEmpty('Current title is required'),
  yearsOfExperience: isInRange({ min: 0, max: 50 }, 'Years of experience must be between 0 and 50'),
  positions: {
    [formRootRule]: isNotEmpty('Add at least one position'),
    company: isNotEmpty('Company is required'),
    title: isNotEmpty('Title is required'),
    years: ([start, end]) => {
      if (!start || !end) {
        return 'Select start and end year';
      }
      return dayjs(end).isBefore(start, 'year') ? 'End year cannot be before start year' : null;
    },
  },
  startDate: (value) => {
    if (!value) {
      return 'Select your earliest start date';
    }
    return dayjs(value).isBefore(dayjs(), 'day') ? 'Start date cannot be in the past' : null;
  },
  workMode: isNotEmpty('Select a work arrangement'),
  notes: hasLength(
    { max: NOTES_MAX_LENGTH },
    `Notes must be ${NOTES_MAX_LENGTH} characters or less`
  ),
};

// Paths in visual order, so the first invalid one is the field to focus
export function getStepFields(step: number, values: JobApplicationValues): string[] {
  switch (step) {
    case 0:
      return ['firstName', 'lastName', 'email', 'phone', 'linkedinUrl'];
    case 1:
      return [
        'currentTitle',
        'yearsOfExperience',
        ...values.positions.flatMap((_, index) => [
          `positions.${index}.company`,
          `positions.${index}.title`,
          `positions.${index}.years`,
        ]),
        'positions',
      ];
    case 2:
      return ['startDate', 'expectedSalary', 'workMode', 'notes'];
    default:
      return [];
  }
}

const FIELD_STEPS: Record<keyof JobApplicationValues, number> = {
  firstName: 0,
  lastName: 0,
  email: 0,
  phone: 0,
  linkedinUrl: 0,
  currentTitle: 1,
  yearsOfExperience: 1,
  positions: 1,
  startDate: 2,
  expectedSalary: 2,
  workMode: 2,
  notes: 2,
};

export function getStepOfField(path: string) {
  return FIELD_STEPS[path.split('.')[0] as keyof JobApplicationValues] ?? 0;
}
